WITH flattened_attrs AS (SELECT id, plan, currency, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT *, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY entry_price ASC, id ASC) AS row_seq, NTILE(10) OVER (PARTITION BY plan ORDER BY avg_tier_price DESC, id ASC) AS avg_tier_price_bucket, AVG(entry_price) OVER (PARTITION BY plan, currency ORDER BY entry_price ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS entry_price_avg_2_prior FROM flattened_attrs;
